-- guile
insert into moves (character_id, category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, patch_id, is_published, sort_order)
select c.id, v.category::move_category, v.name, v.input_classic, v.damage, v.startup, v.active, v.recovery, v.on_hit, v.on_block, v.notes,
       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '5', '3', '7', '+4', '-2', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 0),
  ('normal', '{"ko":"서서 중펀치","en":"Standing Medium Punch"}'::jsonb, '5MP', '600', '7', '3', '15', '+6', '0', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 1),
  ('normal', '{"ko":"서서 강펀치","en":"Standing Heavy Punch"}'::jsonb, '5HP', '900', '7', '3', '23', '-1', '-6', '{"ko":"판정: 상단\n20% damage scaling to followup combo hits.","en":"Hit level: High\n20% damage scaling to followup combo hits."}'::jsonb, 2),
  ('normal', '{"ko":"서서 약킥","en":"Standing Light Kick"}'::jsonb, '5LK', '300', '5', '3', '12', '+3', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 3),
  ('normal', '{"ko":"서서 중킥","en":"Standing Medium Kick"}'::jsonb, '5MK', '700', '7', '5', '18', '+1', '-4', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 4),
  ('normal', '{"ko":"서서 강킥","en":"Standing Heavy Kick"}'::jsonb, '5HK', '800', '12', '3', '21', '+4', '-4', '{"ko":"판정: 상단\nJune 2025 patch: initial scaling of 20%. As of August 2026 patch: startup from 13 to 12 frames.","en":"Hit level: High\nJune 2025 patch: initial scaling of 20%. As of August 2026 patch: startup from 13 to 12 frames."}'::jsonb, 5),
  ('normal', '{"ko":"앉아 약펀치","en":"Crouching Light Punch"}'::jsonb, '2LP', '300', '4', '3', '8', '+5', '-2', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 6),
  ('normal', '{"ko":"앉아 중펀치","en":"Crouching Medium Punch"}'::jsonb, '2MP', '600', '6', '3', '13 (16 on whiff)', '+4', '-2', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 7),
  ('normal', '{"ko":"앉아 강펀치","en":"Crouching Heavy Punch"}'::jsonb, '2HP', '900', '9', '5', '20', '0', '-9', '{"ko":"판정: 상단\nAs of March 2026 patch: now special/super cancellable.","en":"Hit level: High\nAs of March 2026 patch: now special/super cancellable."}'::jsonb, 8),
  ('normal', '{"ko":"앉아 약킥","en":"Crouching Light Kick"}'::jsonb, '2LK', '200', '5', '2', '12', '+1', '-3', '{"ko":"판정: 하단\nJune 2025 patch: recovery from 13 to 12, on block from -5 to -3.","en":"Hit level: Low\nJune 2025 patch: recovery from 13 to 12, on block from -5 to -3."}'::jsonb, 9),
  ('normal', '{"ko":"앉아 중킥","en":"Crouching Medium Kick"}'::jsonb, '2MK', '500', '8', '3', '18', '+4', '-4', '{"ko":"판정: 하단\n10% damage scaling to followup combo hits.","en":"Hit level: Low\n10% damage scaling to followup combo hits."}'::jsonb, 10),
  ('normal', '{"ko":"앉아 강킥","en":"Crouching Heavy Kick"}'::jsonb, '2HK', '450, 450', '9, 27', '2, 3', '21', 'Knockdown +34', '-12', '{"ko":"판정: 하단","en":"Hit level: Low"}'::jsonb, 11),
  ('unique', '{"ko":"Back + Light Kick","en":"Back + Light Kick"}'::jsonb, '', '500', '8', '5', '15', '0...', '-4...', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 12),
  ('unique', '{"ko":"Forward + Medium Punch","en":"Forward + Medium Punch"}'::jsonb, '', '800', '20', '3', '19', '+2', '-3', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 13),
  ('unique', '{"ko":"Forward/Back + Medium Kick","en":"Forward/Back + Medium Kick"}'::jsonb, '', '700', '11 (11)', '3', '21 (18)', '+3 (+3)', '-6 (-6)', '{"ko":"판정: 상단\nForward first, Back in parenthesis.","en":"Hit level: High\nForward first, Back in parenthesis."}'::jsonb, 14),
  ('unique', '{"ko":"Forward + Heavy Punch","en":"Forward + Heavy Punch"}'::jsonb, '', '800', '16', '3', '20', '+5', '+3', '{"ko":"판정: 상단\nWhiffs on crouching opponents.","en":"Hit level: High\nWhiffs on crouching opponents."}'::jsonb, 15),
  ('unique', '{"ko":"Back + Heavy Punch","en":"Back + Heavy Punch"}'::jsonb, '', '800', '9', '3', '21', '+1', '-4', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 16),
  ('unique', '{"ko":"Forward + Heavy Kick","en":"Forward + Heavy Kick"}'::jsonb, '', '1000', '17', '3', '26', '-1', '-8', '{"ko":"판정: 상단\nKnockdown +29 on Counter Hit. Crumple +55 on Punish Counter Hit. Anti-air counter-hit causes a knockdown juggle state as of May 2024 patch.","en":"Hit level: High\nKnockdown +29 on Counter Hit. Crumple +55 on Punish Counter Hit. Anti-air counter-hit causes a knockdown juggle state as of May 2024 patch."}'::jsonb, 17),
  ('unique', '{"ko":"Guile High Kick (Down-Forward + Heavy Kick)","en":"Guile High Kick (Down-Forward + Heavy Kick)"}'::jsonb, '3HK', '1000', '10', '3', '23', '0', '-9', '{"ko":"판정: 상단\nJune 2025 patch: increased juggle height and hit stun on punish counter.","en":"Hit level: High\nJune 2025 patch: increased juggle height and hit stun on punish counter."}'::jsonb, 18),
  ('target_combo', '{"ko":"Medium Punch, Back + Heavy Punch","en":"Medium Punch, Back + Heavy Punch"}'::jsonb, '', '600, 600', '7, 16', '3, 3', '15, 26', '+6, Knockdown +35', '0, -9', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 19),
  ('target_combo', '{"ko":"Down + Medium Punch, Down + Medium Punch (Drake Fang)","en":"Down + Medium Punch, Down + Medium Punch (Drake Fang)"}'::jsonb, 'Drake Fang', '600, 600', '6, 12', '3, 3', '13, 16', '+4, Knockdown +44', '-2, -6', '{"ko":"판정: 상단\nAs of March 2026 patch: second hit now ground bounces into limited juggle state if first hit is a counter.","en":"Hit level: High\nAs of March 2026 patch: second hit now ground bounces into limited juggle state if first hit is a counter."}'::jsonb, 20),
  ('target_combo', '{"ko":"Down + Medium Kick, Forward + Medium Punch","en":"Down + Medium Kick, Forward + Medium Punch"}'::jsonb, '', '500, 800', '8, 20', '3, 3', '18, 21', '+4, +1', '-5, -5', '{"ko":"판정: Low, High\nSecond hit scales to 80% (640).","en":"Hit level: Low, High\nSecond hit scales to 80% (640)."}'::jsonb, 21),
  ('target_combo', '{"ko":"Down + Heavy Kick, Down-Forward + Heavy Kick","en":"Down + Heavy Kick, Down-Forward + Heavy Kick"}'::jsonb, '', '450, 600', '9, 10', '2, 3', '25', '--, Knockdown +34', '--, -10', '{"ko":"판정: Low, High\nSecond hit only combos if first hit is Punish Counter (which causes Juggle State). Second hit scales to 80% (480).","en":"Hit level: Low, High\nSecond hit only combos if first hit is Punish Counter (which causes Juggle State). Second hit scales to 80% (480)."}'::jsonb, 22),
  ('normal', '{"ko":"Jump Light Punch","en":"Jump Light Punch"}'::jsonb, '', '300', '4', '10', '3 Landing', '+5...', '+1...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 23),
  ('normal', '{"ko":"Jump Medium Punch","en":"Jump Medium Punch"}'::jsonb, '', '700', '7', '3', '3 Landing', '+10...', '+6...', '{"ko":"판정: 중단\nJuggle state on air hit.","en":"Hit level: Overhead\nJuggle state on air hit."}'::jsonb, 24),
  ('normal', '{"ko":"Jump Heavy Punch","en":"Jump Heavy Punch"}'::jsonb, '', '800', '9', '4', '3 Landing', '+9...', '+4...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 25),
  ('normal', '{"ko":"Jump Light Kick","en":"Jump Light Kick"}'::jsonb, '', '300', '6', '10', '3 Landing', '+4...', '+0...', '{"ko":"판정: 중단\nCrosses up.","en":"Hit level: Overhead\nCrosses up."}'::jsonb, 26),
  ('normal', '{"ko":"Jump Medium Kick","en":"Jump Medium Kick"}'::jsonb, '', '600', '7', '7', '3 Landing', '+9...', '+5...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 27),
  ('normal', '{"ko":"Jump Heavy Kick","en":"Jump Heavy Kick"}'::jsonb, '', '800', '10', '5', '3 Landing', '+10...', '+6...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 28),
  ('special', '{"ko":"Sonic Boom","en":"Sonic Boom"}'::jsonb, '(4 모으기) 6P', '550 (600)', '10', '**', '30', '+3... (+4...)', '-3... (-3...)', '{"ko":"판정: 상단\nPerfect in Parenthesis. Strength of the Punch only changes the Sonic Boom''s travel speed, does not change advantage or damage.","en":"Hit level: High\nPerfect in Parenthesis. Strength of the Punch only changes the Sonic Boom''s travel speed, does not change advantage or damage."}'::jsonb, 29),
  ('special', '{"ko":"Sonic Boom (Overdrive)","en":"Sonic Boom (Overdrive)"}'::jsonb, '(4 모으기) 6PP', '500, 500', '10', '**', '30', 'Variable Knockdown of +48 minimum', '+3', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 30),
  ('special', '{"ko":"Flash Kick (LK)","en":"Flash Kick (LK)"}'::jsonb, '(2 모으기) 8LK', '1000 (1200)', '5', '6', '41', 'Knockdown +36...', '-30', '{"ko":"판정: 상단\nPerfect in parenthesis. Anti-air invincible on frames 1-7.","en":"Hit level: High\nPerfect in parenthesis. Anti-air invincible on frames 1-7."}'::jsonb, 31),
  ('special', '{"ko":"Flash Kick (MK)","en":"Flash Kick (MK)"}'::jsonb, '(2 모으기) 8MK', '1100 (1300)', '6', '6', '42', 'Knockdown +37...', '-31', '{"ko":"판정: 상단\nPerfect in parenthesis. Anti-air invincible on frames 1-8.","en":"Hit level: High\nPerfect in parenthesis. Anti-air invincible on frames 1-8."}'::jsonb, 32),
  ('special', '{"ko":"Flash Kick (HK)","en":"Flash Kick (HK)"}'::jsonb, '(2 모으기) 8HK', '1200 (1400)', '7', '6', '42', 'Knockdown +37...', '-31', '{"ko":"판정: 상단\nPerfect in parenthesis. Anti-air invincible on frames 1-9.","en":"Hit level: High\nPerfect in parenthesis. Anti-air invincible on frames 1-9."}'::jsonb, 33),
  ('special', '{"ko":"Flash Kick (Overdrive)","en":"Flash Kick (Overdrive)"}'::jsonb, '(2 모으기) 8KK', '1000, 600', '6', '6', '46', 'Knockdown +29...', '-33', '{"ko":"판정: 상단\nFully invincible on frames 1-11.","en":"Hit level: High\nFully invincible on frames 1-11."}'::jsonb, 34),
  ('special', '{"ko":"Sonic Blade (LP)","en":"Sonic Blade (LP)"}'::jsonb, '214LP', '400', '16', '...27', '26', '-3', '-4', '{"ko":"판정: 상단\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created.","en":"Hit level: High\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created."}'::jsonb, 35),
  ('special', '{"ko":"Sonic Blade (MP)","en":"Sonic Blade (MP)"}'::jsonb, '214MP', '400', '21', '...30', '29', '-6', '-7', '{"ko":"판정: 상단\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created.","en":"Hit level: High\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created."}'::jsonb, 36),
  ('special', '{"ko":"Sonic Blade (HP)","en":"Sonic Blade (HP)"}'::jsonb, '214HP', '250, 250', '31', '...24', '19', '+1', '-1', '{"ko":"판정: 상단\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created.","en":"Hit level: High\nCan cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created."}'::jsonb, 37),
  ('special', '{"ko":"Sonic Blade (Overdrive)","en":"Sonic Blade (Overdrive)"}'::jsonb, '214PP', '300', '15', '...21', '**', 'Knockdown +54...', '+1', '{"ko":"판정: 상단\nLimited Juggle State on hit. Can cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created. As of August 2026 patch: on-block from -4 to +1.","en":"Hit level: High\nLimited Juggle State on hit. Can cancel into Sonic Boom with Foward + Punch, no charge required. If the Sonic Boom touches the Sonic Blade, a Sonic Cross is created. As of August 2026 patch: on-block from -4 to +1."}'::jsonb, 38),
  ('special', '{"ko":"Sonic Cross","en":"Sonic Cross"}'::jsonb, 'Sonic Blade > Forward + Punch (PP)', '600, 400 (400, 400, 500)', '10', '**', '**', 'Knockdown +**...', '**', '{"ko":"판정: 상단\nPunch strength only changes the travel speed, not the damage or advantage. Overdrive in parenthesis.","en":"Hit level: High\nPunch strength only changes the travel speed, not the damage or advantage. Overdrive in parenthesis."}'::jsonb, 39),
  ('special', '{"ko":"Sonic Break","en":"Sonic Break"}'::jsonb, 'During Solid Puncher: PP (chargeless) or P (after Sonic Boom)', '600 (1000)', '11', '**', '25', '+2', '-2', '{"ko":"판정: 상단\nFor the chargeless PP version, there is no difference in travel speed based on punch used. For the P followup to Sonic Boom, the travel speed does change based on the punch used. Overdrive Sonic Boom followup does 1000 damage.","en":"Hit level: High\nFor the chargeless PP version, there is no difference in travel speed based on punch used. For the P followup to Sonic Boom, the travel speed does change based on the punch used. Overdrive Sonic Boom followup does 1000 damage."}'::jsonb, 40),
  ('super', '{"ko":"Sonic Hurricane (Level 1)","en":"Sonic Hurricane (Level 1)"}'::jsonb, '(4 모으기) 646P', '2000 (1800)', '8 (7)', '**', '81 (68)', 'Knockdown +41 (Knockdown +70)', '-26 (-2)', '{"ko":"판정: 상단\nStrike/throw invincible on frames 1-10 (Light and Medium versions only!). Breaks armor. Hard punch has no invincibility, angles the projectile upward, data in parenthesis.","en":"Hit level: High\nStrike/throw invincible on frames 1-10 (Light and Medium versions only!). Breaks armor. Hard punch has no invincibility, angles the projectile upward, data in parenthesis."}'::jsonb, 41),
  ('super', '{"ko":"Solid Puncher (Level 2)","en":"Solid Puncher (Level 2)"}'::jsonb, '214214P', null, '6', null, null, null, null, '{"ko":"Enables Sonic Break. 25 second timer.","en":"Enables Sonic Break. 25 second timer."}'::jsonb, 42),
  ('super', '{"ko":"Crossfire Somersault (Level 3)","en":"Crossfire Somersault (Level 3)"}'::jsonb, '(4 모으기) 646K', '4000 (4500)', '9', '6', '70', 'Knockdown +16 (Knockdown +16)', '-59', '{"ko":"판정: 상단\nFully invincible on frames 1-14. Breaks armor. Critical Art in parenthesis.","en":"Hit level: High\nFully invincible on frames 1-14. Breaks armor. Critical Art in parenthesis."}'::jsonb, 43),
  ('throw', '{"ko":"Forward Throw","en":"Forward Throw"}'::jsonb, 'f.throw', '1200', '5', '3', '23', '+15', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 44),
  ('throw', '{"ko":"Back Throw","en":"Back Throw"}'::jsonb, 'b.throw', '1200', '5', '3', '23', '+18', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 45),
  ('throw', '{"ko":"Forward Air Throw","en":"Forward Air Throw"}'::jsonb, 'throw', '1200', '5', '3', '**', '**', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 46),
  ('throw', '{"ko":"Back Air Throw","en":"Back Air Throw"}'::jsonb, 'throw', '1200', '5', '3', '**', '**', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 47)
) as v(category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, ord)
where c.slug = 'guile' and not exists (select 1 from moves m where m.character_id = c.id);

-- dhalsim
insert into moves (character_id, category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, patch_id, is_published, sort_order)
select c.id, v.category::move_category, v.name, v.input_classic, v.damage, v.startup, v.active, v.recovery, v.on_hit, v.on_block, v.notes,
       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '4', '3', '8', '+4', '-1', '{"ko":"판정: 상단\nAugust 2026 patch: expanded hitbox upward.","en":"Hit level: High\nAugust 2026 patch: expanded hitbox upward."}'::jsonb, 0),
  ('normal', '{"ko":"서서 중펀치","en":"Standing Medium Punch"}'::jsonb, '5MP', '700', '14', '3', '19', '0', '-5', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 1),
  ('normal', '{"ko":"서서 강펀치","en":"Standing Heavy Punch"}'::jsonb, '5HP', '1000', '16', '7', '22', '-6...', '-10...', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 2),
  ('normal', '{"ko":"서서 약킥","en":"Standing Light Kick"}'::jsonb, '5LK', '300', '9', '4', '11', '+2', '-6', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 3),
  ('normal', '{"ko":"서서 중킥","en":"Standing Medium Kick"}'::jsonb, '5MK', '600', '12', '3', '18', '-2', '-6', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 4),
  ('normal', '{"ko":"서서 강킥","en":"Standing Heavy Kick"}'::jsonb, '5HK', '800', '17', '3', '20', '+3', '-6', '{"ko":"판정: 상단\nLimited Juggle State on anti-air hit. +24 on Punish Counter as of October 2024 patch.","en":"Hit level: High\nLimited Juggle State on anti-air hit. +24 on Punish Counter as of October 2024 patch."}'::jsonb, 5),
  ('normal', '{"ko":"앉아 약펀치","en":"Crouching Light Punch"}'::jsonb, '2LP', '300', '5', '3', '9', '+4', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 6),
  ('normal', '{"ko":"앉아 중펀치","en":"Crouching Medium Punch"}'::jsonb, '2MP', '600', '12', '3', '16', '0', '-4', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 7),
  ('normal', '{"ko":"앉아 강펀치","en":"Crouching Heavy Punch"}'::jsonb, '2HP', '800', '19', '4', '24', '+3', '-8', '{"ko":"판정: 하단\nJune 2025 patch: extended hurtbox.","en":"Hit level: Low\nJune 2025 patch: extended hurtbox."}'::jsonb, 8),
