  ('normal', '{"ko":"Jump, Down + Light Punch (Yoga Mummy)","en":"Jump, Down + Light Punch (Yoga Mummy)"}'::jsonb, 'Yoga Mummy', '500', '10', '**', '9 Landing', '-16...+8', '-20...+4', '{"ko":"판정: 상단\nCan be done off of a back, neutral, or forward jump. Active until landing. Lower/farther angle increases advantage on hit/block. Air-to-air hit causes a knockdown with juggle potential as of May 2024 patch.","en":"Hit level: High\nCan be done off of a back, neutral, or forward jump. Active until landing. Lower/farther angle increases advantage on hit/block. Air-to-air hit causes a knockdown with juggle potential as of May 2024 patch."}'::jsonb, 26),
  ('normal', '{"ko":"Jump, Down + K (Drill Kick)","en":"Jump, Down + K (Drill Kick)"}'::jsonb, 'Drill Kick', '500', '9', '**', '11 Landing (6 Landing)', '-20...+10', '-27...+5', '{"ko":"판정: 상단\nCan be done off of a back, neutral, or forward jump. Active until landing. Lower/farther angle increases advantage on hit/block. Kick strength changes trajectory: Light Kick is the farthest while Heavy Kick is the shortest. 20% damage scaling to followup combo hits. Less landing recovery on hit/block than on whiff.","en":"Hit level: High\nCan be done off of a back, neutral, or forward jump. Active until landing. Lower/farther angle increases advantage on hit/block. Kick strength changes trajectory: Light Kick is the farthest while Heavy Kick is the shortest. 20% damage scaling to followup combo hits. Less landing recovery on hit/block than on whiff."}'::jsonb, 27),
  ('special', '{"ko":"Yoga Fire","en":"Yoga Fire"}'::jsonb, '236P', '600 (400, 400)', '15 (45)', '**', '33 (33)', '-2... (Knockdown +49...)', '-2... (-1...)', '{"ko":"판정: 상단\nStrength of the Punch only changes the Yoga Fire''s travel speed, does not change advantage or damage. Hold data in parenthesis.","en":"Hit level: High\nStrength of the Punch only changes the Yoga Fire''s travel speed, does not change advantage or damage. Hold data in parenthesis."}'::jsonb, 28),
  ('special', '{"ko":"Yoga Fire (Overdrive)","en":"Yoga Fire (Overdrive)"}'::jsonb, '236PP', '500, 500', '12', '**', '33', 'Knockdown +49...', '-3...', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 29),
  ('special', '{"ko":"Yoga Arch","en":"Yoga Arch"}'::jsonb, '236K', '600', '18', '**', '27', '+1 ("+29")', '-1 ("+27")', '{"ko":"판정: 상단\nStrength of the Kick changes the trajectory, does not change advantage or damage. Except for at point blank, Dhalsim recovers before the lobbed projectile can hit a grounded opponent, so the advantage is +29 from hitstun (+27 blockstun), assuming you count from the falling projectile hitting someone post-recovery.","en":"Hit level: High\nStrength of the Kick changes the trajectory, does not change advantage or damage. Except for at point blank, Dhalsim recovers before the lobbed projectile can hit a grounded opponent, so the advantage is +29 from hitstun (+27 blockstun), assuming you count from the falling projectile hitting someone post-recovery."}'::jsonb, 30),
  ('special', '{"ko":"Yoga Arch (Overdrive)","en":"Yoga Arch (Overdrive)"}'::jsonb, '236KK', '500, 500', '18', '**', '27', '+1 ("+29") ("+22")', '-3 ("+25") ("+18")', '{"ko":"판정: 상단\nLK+MK/MK+HK/LK+HK changes the trajectory, does not change advantage or damage. Except for at point blank, Dhalsim recovers before the lobbed projectile can hit a grounded opponent, so the advantage from any bouncing hit is +29 from hitstun (+25 blockstun), assuming you count from the falling projectile hitting someone post-recovery. The final ground explosion is +22 hitstun (+18 blockstun). Followup bouncing attack tracks opponent after the first bounce only.","en":"Hit level: High\nLK+MK/MK+HK/LK+HK changes the trajectory, does not change advantage or damage. Except for at point blank, Dhalsim recovers before the lobbed projectile can hit a grounded opponent, so the advantage from any bouncing hit is +29 from hitstun (+25 blockstun), assuming you count from the falling projectile hitting someone post-recovery. The final ground explosion is +22 hitstun (+18 blockstun). Followup bouncing attack tracks opponent after the first bounce only."}'::jsonb, 31),
