  ('super', '{"ko":"Yoga Inferno (Level 1)","en":"Yoga Inferno (Level 1)"}'::jsonb, '236236P', '(1920) (2100) (2040)', '10', '**', '(20) (20) (40)', '(Knockdown +24) (Knockdown +24) (Knockdown +27)', '(-15) (-15) (-22)', '{"ko":"판정: 상단\nNo invincibility. Breaks armor. Light Punch goes the farthest, Medium Punch does the most damage, Heavy Punch aims upward and has more knockdown advantage. Data listed as: (Light Punch) (Medium Punch) (Heavy Punch).","en":"Hit level: High\nNo invincibility. Breaks armor. Light Punch goes the farthest, Medium Punch does the most damage, Heavy Punch aims upward and has more knockdown advantage. Data listed as: (Light Punch) (Medium Punch) (Heavy Punch)."}'::jsonb, 44),
  ('super', '{"ko":"Yoga Sunburst (Level 2)","en":"Yoga Sunburst (Level 2)"}'::jsonb, '214214K', '**', '7 (7+???)', '7 (3)', '9', null, null, '{"ko":"판정: 상단\nFully invincible on frames 1-6. Breaks armor. Charge version in parenthesis. If opponent hits the charging hitbox before. The damage is weird based on when this move hits or how long it''s charged, I''ll calculate it... some other time, luuuul.","en":"Hit level: High\nFully invincible on frames 1-6. Breaks armor. Charge version in parenthesis. If opponent hits the charging hitbox before. The damage is weird based on when this move hits or how long it''s charged, I''ll calculate it... some other time, luuuul."}'::jsonb, 45),
  ('super', '{"ko":"Merciless Yoga (Level 3)","en":"Merciless Yoga (Level 3)"}'::jsonb, '236236K', '4000 (4500)', '10', '5', '75', 'Knockdown +19 (Knockdown +19)', '-62', '{"ko":"판정: 상단\nFully invincible on frames 1-14. Breaks armor. Critical Art in parenthesis.","en":"Hit level: High\nFully invincible on frames 1-14. Breaks armor. Critical Art in parenthesis."}'::jsonb, 46),
  ('throw', '{"ko":"Forward Throw","en":"Forward Throw"}'::jsonb, 'f.throw', '1200', '5', '3', '23', '+31', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 47),
  ('throw', '{"ko":"Back Throw","en":"Back Throw"}'::jsonb, 'b.throw', '1200', '5', '3', '23', '+19', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 48)
) as v(category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, ord)
where c.slug = 'dhalsim' and not exists (select 1 from moves m where m.character_id = c.id);

-- deejay
insert into moves (character_id, category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, patch_id, is_published, sort_order)
select c.id, v.category::move_category, v.name, v.input_classic, v.damage, v.startup, v.active, v.recovery, v.on_hit, v.on_block, v.notes,
       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
