  ('normal', '{"ko":"앉아 강펀치","en":"Crouching Heavy Punch"}'::jsonb, '2HP', '800', '8', '2', '20', '+6', '-2', '{"ko":"판정: 상단\nForces stand on hit. As of March 2026 patch: expanded front hurtbox.","en":"Hit level: High\nForces stand on hit. As of March 2026 patch: expanded front hurtbox."}'::jsonb, 8),
  ('normal', '{"ko":"앉아 약킥","en":"Crouching Light Kick"}'::jsonb, '2LK', '200', '5', '2', '10', '+2', '-2', '{"ko":"판정: 하단\nAs of August 2026 patch: reduced pushback on hit and block.","en":"Hit level: Low\nAs of August 2026 patch: reduced pushback on hit and block."}'::jsonb, 9),
