  ('unique', '{"ko":"Speedy Maracas","en":"Speedy Maracas"}'::jsonb, '', null, '133...', null, null, null, null, '{"ko":"Builds super meter as long as Dee Jay dances. Continues dancing until punch buttons are released. Minimum 133 frames. Can be cancelled into from Air Slasher.","en":"Builds super meter as long as Dee Jay dances. Continues dancing until punch buttons are released. Minimum 133 frames. Can be cancelled into from Air Slasher."}'::jsonb, 14),
  ('target_combo', '{"ko":"Threebeat Combo (Light Punch, Medium Kick, Medium Kick)","en":"Threebeat Combo (Light Punch, Medium Kick, Medium Kick)"}'::jsonb, 'LP → MK → MK', '300, 400, 625', '4, 9, 14', '3, 3, 3', '6, 20, 19', '+4, +2, +3', '-1, -3, -8', '{"ko":"판정: 상단\nSecond hit always scales to 80%, third hit to 70%.","en":"Hit level: High\nSecond hit always scales to 80%, third hit to 70%."}'::jsonb, 15),
