  ('target_combo', '{"ko":"Funky Dance (Medium Punch, Medium Punch, Heavy Punch (Back + Heavy Punch))","en":"Funky Dance (Medium Punch, Medium Punch, Heavy Punch (Back + Heavy Punch))"}'::jsonb, '', '600, 500, 900', '7, 12, 20 (--)', '3, 2, 2 (--)', '13, 17, 24 (23)', '+5, +2, Knockdown +43 (-4)', '+2, -2, -8 (-6)', '{"ko":"판정: 상단\nThird hit does not combo, but leaves a 3 frame gap between the second and third hit, which is a frametrap. Using Back + Heavy Punch cancels the third hit, but leaves DeeJay at -3 on hit (-5 on block) after the second hit.","en":"Hit level: High\nThird hit does not combo, but leaves a 3 frame gap between the second and third hit, which is a frametrap. Using Back + Heavy Punch cancels the third hit, but leaves DeeJay at -3 on hit (-5 on block) after the second hit."}'::jsonb, 17),
