  ('special', '{"ko":"Russian Suplex / Siberian Express","en":"Russian Suplex / Siberian Express"}'::jsonb, '63214K', '2900 / 2700', '10 / 28...80', '2', '50 / 41', 'Knockdown +26 / Knockdown +29', null, '{"ko":"판정: 잡기\nDoes Russian Suplex if close to opponent, does Siberian Express if mid range or far from opponent. Technically two different versions of Siberian Express, based on mid range or far range. Siberian Express has one hit of armor, but only on the far ranged version.","en":"Hit level: Throw\nDoes Russian Suplex if close to opponent, does Siberian Express if mid range or far from opponent. Technically two different versions of Siberian Express, based on mid range or far range. Siberian Express has one hit of armor, but only on the far ranged version."}'::jsonb, 36),
  ('special', '{"ko":"Russian Suplex (Overdrive) / Siberian Express (Overdrive)","en":"Russian Suplex (Overdrive) / Siberian Express (Overdrive)"}'::jsonb, '63214K', '3200 / 3000', '10 / 23...80', '2', '50 / 44', 'Knockdown +27 / Knockdown +29', null, '{"ko":"판정: 잡기\nDoes Russian Suplex if close to opponent, , does Siberian Express if mid range or far from opponent. Technically two different versions of Siberian Express, based on mid range or far range. Overdrive Siberian Express has two hits of armor, but only on the far range version, starting on frame 3 and lasting until the grab activates.","en":"Hit level: Throw\nDoes Russian Suplex if close to opponent, , does Siberian Express if mid range or far from opponent. Technically two different versions of Siberian Express, based on mid range or far range. Overdrive Siberian Express has two hits of armor, but only on the far range version, starting on frame 3 and lasting until the grab activates."}'::jsonb, 37),
  ('special', '{"ko":"Tundra Storm","en":"Tundra Storm"}'::jsonb, '22HK', '2400', '6', '50', '24', 'Knockdown +5', null, '{"ko":"판정: Parry\nSpecifically parries standing kick attacks (normals, specials, and drive impacts are all possible if the move is a standing kick).","en":"Hit level: Parry\nSpecifically parries standing kick attacks (normals, specials, and drive impacts are all possible if the move is a standing kick)."}'::jsonb, 38),
