  ('normal', '{"ko":"서서 중킥","en":"Standing Medium Kick"}'::jsonb, '5MK', '540', '9', '3', '17 (18 on whiff)', '+2', '-3', '{"ko":"판정: 상단\nHurtbox expanded after active frames on June 2025 patch.","en":"Hit level: High\nHurtbox expanded after active frames on June 2025 patch."}'::jsonb, 4),
  ('normal', '{"ko":"서서 강킥","en":"Standing Heavy Kick"}'::jsonb, '5HK', '720', '15', '3', '21', '+3', '-5', '{"ko":"판정: 상단\nCrumple of +71 on Punish Counter. Limited Juggle State on anti-air hit. As of December 2024 patch: \"Reduced the hurtbox on the front legs during the attack''s start up\" was reported in the official patch notes... however, the hurtbox reduction is actually on his **hands** and on frames 5-8. Additionally, the move now has Anti-air invulnerability on frame 14 (1 frame before first active), which it did not have before. Advantage on hit changed from +1 to +3 in June 2025 patch. As of August 2026 patch: hitbox on 2nd frame expanded forward.","en":"Hit level: High\nCrumple of +71 on Punish Counter. Limited Juggle State on anti-air hit. As of December 2024 patch: \"Reduced the hurtbox on the front legs during the attack''s start up\" was reported in the official patch notes... however, the hurtbox reduction is actually on his **hands** and on frames 5-8. Additionally, the move now has Anti-air invulnerability on frame 14 (1 frame before first active), which it did not have before. Advantage on hit changed from +1 to +3 in June 2025 patch. As of August 2026 patch: hitbox on 2nd frame expanded forward."}'::jsonb, 5),
  ('normal', '{"ko":"앉아 약펀치","en":"Crouching Light Punch"}'::jsonb, '2LP', '225', '4', '2', '9', '+5', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 6),
  ('normal', '{"ko":"앉아 중펀치","en":"Crouching Medium Punch"}'::jsonb, '2MP', '540', '6', '3', '13 (15 on whiff)', '+5', '-1', '{"ko":"판정: 상단\nAs of June 2025 patch: hurtbox on feet increased vertically (to the top) on frames 16-17 on whiff. Feet hurtbox removed on frames 16-17 on hit/block.","en":"Hit level: High\nAs of June 2025 patch: hurtbox on feet increased vertically (to the top) on frames 16-17 on whiff. Feet hurtbox removed on frames 16-17 on hit/block."}'::jsonb, 7),
  ('normal', '{"ko":"앉아 강펀치","en":"Crouching Heavy Punch"}'::jsonb, '2HP', '810', '8', '5', '23', '0', '-8', '{"ko":"판정: 상단\nAs of June 2025 patch: startup reduced from 9 frames to 8 frames.","en":"Hit level: High\nAs of June 2025 patch: startup reduced from 9 frames to 8 frames."}'::jsonb, 8),
  ('normal', '{"ko":"앉아 약킥","en":"Crouching Light Kick"}'::jsonb, '2LK', '180', '5', '2', '11', '+3', '-3', '{"ko":"판정: 하단\nAs of March 2026 patch: +3 on hit.","en":"Hit level: Low\nAs of March 2026 patch: +3 on hit."}'::jsonb, 9),
