  ('unique', '{"ko":"Forward + Heavy Kick (Senei Kick)","en":"Forward + Heavy Kick (Senei Kick)"}'::jsonb, 'Senei Kick', '810 [990]', '16', '3 [4]', '20 [19]', '+3', '-3', '{"ko":"판정: 상단\nAt 4 Drinks, can Target Combo, 4 Drinks data listed in bracket.","en":"Hit level: High\nAt 4 Drinks, can Target Combo, 4 Drinks data listed in bracket."}'::jsonb, 15),
  ('target_combo', '{"ko":"Down + Heavy Kick, Heavy Kick, Punch","en":"Down + Heavy Kick, Heavy Kick, Punch"}'::jsonb, '', '(360, 360), 450, --', '(9, 13), 12, --', '2, 4, 4', '(28), 43, 61', '(Knockdown +33), Knockdown +22, Knockdown +4', '(-10), -28, -46', '{"ko":"판정: (Low, Low), High, Drink\nThird \"hit\" is a cancel into Drink.","en":"Hit level: (Low, Low), High, Drink\nThird \"hit\" is a cancel into Drink."}'::jsonb, 16),
