  ('target_combo', '{"ko":"Forward + Medium Kick, Medium Kick, Punch (Full Moon Kick)","en":"Forward + Medium Kick, Medium Kick, Punch (Full Moon Kick)"}'::jsonb, 'Full Moon Kick', '600, (300, 300), --', '22, 15, --', '5, (3, 2), --', '20, 28, 61', '+1, Knockdown +31, Knockdown +2', '-3, -14, -46', '{"ko":"판정: Overhead, (High, High), Drink\nRequires at least 2 Drinks to use, data listed at 2 Drinks. As of June 2025 patch: no longer drinks if kick button is held after 2nd attack hits. As of August 2026 patch: damage from 1000 to 1200, advantage on drink from -1 to +2.","en":"Hit level: Overhead, (High, High), Drink\nRequires at least 2 Drinks to use, data listed at 2 Drinks. As of June 2025 patch: no longer drinks if kick button is held after 2nd attack hits. As of August 2026 patch: damage from 1000 to 1200, advantage on drink from -1 to +2."}'::jsonb, 18),
  ('target_combo', '{"ko":"Back + Heavy Punch, Heavy Punch, Heavy Kick (Intoxicated Assault)","en":"Back + Heavy Punch, Heavy Punch, Heavy Kick (Intoxicated Assault)"}'::jsonb, 'Intoxicated Assault', '840, 630, 840', '18, 21, 21', '4, 4, 3', '20, 20, 37', '+1, +1, Knockdown +23', '-3, -11, -20', '{"ko":"판정: 상단\nRequires at least 3 Drinks to use, data listed at 3 Drinks. Second hit only combos on meaty or counter hit.","en":"Hit level: High\nRequires at least 3 Drinks to use, data listed at 3 Drinks. Second hit only combos on meaty or counter hit."}'::jsonb, 19),
  ('target_combo', '{"ko":"Forward + Heavy Kick, Back + Heavy Kick, Punch (Ransui Haze)","en":"Forward + Heavy Kick, Back + Heavy Kick, Punch (Ransui Haze)"}'::jsonb, 'Ransui Haze', 'Close: 990, --, 935 Middle: 990, --, (330, 330, 660)', 'Close: 16, 25...+14 Middle: 16, 51...+4', 'Close: 4, --, 5 Middle: 4, --, (2, 2, 2)', 'Close: 19, --, 28 Middle: 19, --, 27', 'Close: +3, --, Knockdown +32 Middle: +3, --, Knockdown +35', 'Close: -3, --, -13 Middle: -3, --, -9', '{"ko":"판정: 상단\nRequires 4 Drinks to use, data listed at 4 Drinks. B+HK sways backward for at least 25 frames after the first hit, then Punch activates a different followup based on range: Close is a Headbutt, Middle is a spinning triple punch, and Far is a Drink.","en":"Hit level: High\nRequires 4 Drinks to use, data listed at 4 Drinks. B+HK sways backward for at least 25 frames after the first hit, then Punch activates a different followup based on range: Close is a Headbutt, Middle is a spinning triple punch, and Far is a Drink."}'::jsonb, 20),
  ('normal', '{"ko":"Jump Light Punch","en":"Jump Light Punch"}'::jsonb, '', '270', '5', '9', '3 Landing', '+4...', '+0...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 21),
  ('normal', '{"ko":"Jump Medium Punch","en":"Jump Medium Punch"}'::jsonb, '', '630', '7', '4', '3 Landing', '+10...+11', '+6...+7', '{"ko":"판정: 중단\nLimited Juggle State on air hit.","en":"Hit level: Overhead\nLimited Juggle State on air hit."}'::jsonb, 22),
  ('normal', '{"ko":"Jump Heavy Punch","en":"Jump Heavy Punch"}'::jsonb, '', '720', '10', '6', '3 Landing', '+8...', '+4...', '{"ko":"판정: 중단\nKnockdown on air hit.","en":"Hit level: Overhead\nKnockdown on air hit."}'::jsonb, 23),
  ('normal', '{"ko":"Jump Light Kick","en":"Jump Light Kick"}'::jsonb, '', '270', '6', '6', '3 Landing', '+6...', '+2...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 24),
  ('normal', '{"ko":"Jump Medium Kick","en":"Jump Medium Kick"}'::jsonb, '', '450', '7', '6', '3 Landing', '+9...', '+5...', '{"ko":"판정: 중단\nCrosses up.","en":"Hit level: Overhead\nCrosses up."}'::jsonb, 25),
  ('normal', '{"ko":"Jump Heavy Kick","en":"Jump Heavy Kick"}'::jsonb, '', '360, 360', '8, 16', '3, 4', '3 Landing', '+11...', '+7...', '{"ko":"판정: 중단\nAs of December 2024 patch: now gives limited juggle state on all air-to-air hits.","en":"Hit level: Overhead\nAs of December 2024 patch: now gives limited juggle state on all air-to-air hits."}'::jsonb, 26),
  ('special', '{"ko":"The Devil Inside","en":"The Devil Inside"}'::jsonb, '22P', null, null, null, null, null, null, '{"ko":"판정: Drink\nGrants 1 Drink. In a Counter-Hit state for duration. Can be held to continue drinking. All of Jamie''s normal and special attacks start at 90% Damage scaling with 0 Drinks. Each Drink increases the scaling by 5%, so: 1 Drink: 95% / 2 Drinks: 100% / 3 Drinks: 105% / 4 Drinks: 110%. Additionally, each Drink unlocks a new Target Combo and a new Special Move. At 4 Drinks, some of his Special Moves change as well. Drinking again while at 4 Drinks will instead generate Drive Gauge. No Overdrive version.","en":"Hit level: Drink\nGrants 1 Drink. In a Counter-Hit state for duration. Can be held to continue drinking. All of Jamie''s normal and special attacks start at 90% Damage scaling with 0 Drinks. Each Drink increases the scaling by 5%, so: 1 Drink: 95% / 2 Drinks: 100% / 3 Drinks: 105% / 4 Drinks: 110%. Additionally, each Drink unlocks a new Target Combo and a new Special Move. At 4 Drinks, some of his Special Moves change as well. Drinking again while at 4 Drinks will instead generate Drive Gauge. No Overdrive version."}'::jsonb, 27),
  ('special', '{"ko":"Freeflow Strikes (First Hit)","en":"Freeflow Strikes (First Hit)"}'::jsonb, '236P', '0-3 Drinks: 315 / 360 / 405 / 405 4 Drinks: 220, 220 / 220, 330 / 220, 440 / 220, 440', '0-3 Drinks: 13 / 16 / 19 / 13 4 Drinks: 13 / 16 / 19 / 13', '0-3 Drinks: 2 4 Drinks: 2, 2', '0-3 Drinks: 24 4 Drinks: 20', '0-3 Drinks: -1 / -1 / -1 / +1 4 Drinks: +1 / +1 / +1 / +3', '0-3 Drinks: -6 / -6 / -6 / -3 4 Drinks: -3 / -3 / -3 / -3', '{"ko":"판정: 상단\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\" Is a Rekka style attack, so can be followed up with Forward + Punch once or twice (data for each followup is listed as a separate entry).","en":"Hit level: High\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\" Is a Rekka style attack, so can be followed up with Forward + Punch once or twice (data for each followup is listed as a separate entry)."}'::jsonb, 28),
  ('special', '{"ko":"Freeflow Strikes > Punch Followup 1","en":"Freeflow Strikes > Punch Followup 1"}'::jsonb, 'Freeflow Strikes > Forward + P', '0-3 Drinks: 315 / 360 / 405 / 405 4 Drinks: 220, 275 / 220, 275 / 220, 275 / 220, 330', '0-3 Drinks: 13 / 16 / 19 / 13 4 Drinks: 15 / 15 / 15 / 15', '0-3 Drinks: 2 4 Drinks: 2, 2', '0-3 Drinks: 28 4 Drinks: 27', '0-3 Drinks: -3 / -3 / -3 / -3 4 Drinks: -2 / -2 / -2 / -2', '0-3 Drinks: -13 / -11 / -9 / -9 4 Drinks: -10 / -10 / -10 / -10', '{"ko":"판정: 상단\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\"","en":"Hit level: High\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\""}'::jsonb, 29),
  ('special', '{"ko":"Freeflow Strikes > Punch Followup 2","en":"Freeflow Strikes > Punch Followup 2"}'::jsonb, 'Freeflow Strikes > Forward + P > Forward + P', '0-3 Drinks: 550 / 600 / 650 / 750 4 Drinks: :^)', '0-3 Drinks: 13 / 16 / 19 / 13 4 Drinks: 13 / 16 / 19 / 13', '0-3 Drinks: 2 4 Drinks: 2, 2, 3', '0-3 Drinks: 30 4 Drinks: 28', '0-3 Drinks: Knockdown +27 / KD +27 / KD +27 / KD +28 4 Drinks: Knockdown +27 / KD +27 / KD +27 / KD +28', '0-3 Drinks: -13 / -11 / -9 / -9 4 Drinks: -14 / -14 / -14 / -14', '{"ko":"판정: 상단\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\". Third hit always scales to 72% (396 / 432 / 468 / 540). 4 Drinks version does more scaling, I''ll farm that data out sometime when I hate myself more. June 2025 patch: 20% followup scaling added to normal, 25% followup scaling added to Overdrive version -- but can cancel into Level 3 now.","en":"Hit level: High\nData listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\". Third hit always scales to 72% (396 / 432 / 468 / 540). 4 Drinks version does more scaling, I''ll farm that data out sometime when I hate myself more. June 2025 patch: 20% followup scaling added to normal, 25% followup scaling added to Overdrive version -- but can cancel into Level 3 now."}'::jsonb, 30),
  ('special', '{"ko":"Freeflow Strikes > Kick Followup 1","en":"Freeflow Strikes > Kick Followup 1"}'::jsonb, 'Freeflow Strikes > Forward + K', '225 / 270 / 270 / 315', '14 / 17 / 20 / 14', '2', '28', '-7', '-15', '{"ko":"판정: 상단\nKick stregnth does not change data, it is based off of the originating Punch from Freeflow Strikes. Data listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\".","en":"Hit level: High\nKick stregnth does not change data, it is based off of the originating Punch from Freeflow Strikes. Data listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\"."}'::jsonb, 31),
  ('special', '{"ko":"Freeflow Strikes > Kick Followup 2","en":"Freeflow Strikes > Kick Followup 2"}'::jsonb, 'Freeflow Strikes > Forward + K', '450 / 500 / 550 / 600', '18 / 21 / 24 / 18', '2', '64', 'Knockdown -1 / KD -1 / KD -1 / KD +1 [KD +24]', '-49 / -49 / -49 / -49 [-26]', '{"ko":"판정: 상단\nKick stregnth does not change data, it is based off of the originating Punch from Freeflow Strikes. Data listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\". Third hit always scales to 72% (324 / 360 / 396 / 432). Transitioning into 4 Drinks gives better advantage, listed in brackets.","en":"Hit level: High\nKick stregnth does not change data, it is based off of the originating Punch from Freeflow Strikes. Data listed as \"Light Punch / Medium Punch / Heavy Punch / Overdrive\". Third hit always scales to 72% (324 / 360 / 396 / 432). Transitioning into 4 Drinks gives better advantage, listed in brackets."}'::jsonb, 32),
