  ('special', '{"ko":"Arrow Kick (LK)","en":"Arrow Kick (LK)"}'::jsonb, '623LK', '450, 450', '5', '10', '52', 'Knockdown +42', '-44', '{"ko":"판정: 상단\nAnti-air invincible on frames 1-11. Lower Body invincible on frames 5-22. As of June 2025 patch: active frames from 7 to 10, recovery from 54 to 52 (undocumented: 1 frame less Anti-air invincibility, 1 more frame more Lower Body invinciblity).","en":"Hit level: High\nAnti-air invincible on frames 1-11. Lower Body invincible on frames 5-22. As of June 2025 patch: active frames from 7 to 10, recovery from 54 to 52 (undocumented: 1 frame less Anti-air invincibility, 1 more frame more Lower Body invinciblity)."}'::jsonb, 38),
