  ('special', '{"ko":"Arrow Kick (Overdrive)","en":"Arrow Kick (Overdrive)"}'::jsonb, '623KK', '450, 405, 495', '6', '7', '53', 'Knockdown +40', '-43', '{"ko":"판정: 상단\nFully invincibile on frames 1-9. Anti-air invincible on frames 10-12, Lower Body invincible on frames 10-21.","en":"Hit level: High\nFully invincibile on frames 1-9. Anti-air invincible on frames 10-12, Lower Body invincible on frames 10-21."}'::jsonb, 41),
  ('special', '{"ko":"Luminous Dive Kick","en":"Luminous Dive Kick"}'::jsonb, '(점프) 214K', '950 (760)', '11', '**', '13 Landing', 'Knockdown +43...+52 (KD +59...+65)', '-4...+2 (-3...+3)', '{"ko":"판정: 상단\nRequires 1 Drink to use. Kick strength changes trajectory. Active until landing. Overdrive causes a Limited Juggle State, data in parenthesis. Air to air hit: Normal versions force knockdown, Overdrive version gives ground bounce Limited Juggle State.","en":"Hit level: High\nRequires 1 Drink to use. Kick strength changes trajectory. Active until landing. Overdrive causes a Limited Juggle State, data in parenthesis. Air to air hit: Normal versions force knockdown, Overdrive version gives ground bounce Limited Juggle State."}'::jsonb, 42),
