  ('special', '{"ko":"Bakkai (HK)","en":"Bakkai (HK)"}'::jsonb, '236HK', '250, 250, 250, 250, 250, 250, 300', '25', '**', '32', 'Knockdown +34', '-17', '{"ko":"판정: 상단\nRequires 2 Drinks to use. Projectile invincible on frames 5-35.","en":"Hit level: High\nRequires 2 Drinks to use. Projectile invincible on frames 5-35."}'::jsonb, 45),
