  ('special', '{"ko":"Torbalan (MK)","en":"Torbalan (MK)"}'::jsonb, '236MK', '1000', '(13...)+13', '1', '24', '+6...+27', '-8...+13', '{"ko":"판정: 중단\nHold attack button to feint. Hitbox activates on frame 13 once the ghost gets close enough to the opponent, 26 frames at point blank. Initial scaling of 20%.","en":"Hit level: Overhead\nHold attack button to feint. Hitbox activates on frame 13 once the ghost gets close enough to the opponent, 26 frames at point blank. Initial scaling of 20%."}'::jsonb, 37),
  ('special', '{"ko":"Torbalan (HK)","en":"Torbalan (HK)"}'::jsonb, '236HK', '1000', '(13...)+13', '1', '24', '+6...+27', '-8...+13', '{"ko":"판정: 하단\nHold attack button to feint. Hitbox activates on frame 13 once the ghost gets close enough to the opponent, 26 frames at point blank. Initial scaling of 20%.","en":"Hit level: Low\nHold attack button to feint. Hitbox activates on frame 13 once the ghost gets close enough to the opponent, 26 frames at point blank. Initial scaling of 20%."}'::jsonb, 38),
