  ('unique', '{"ko":"Run (Forward, Hold Forward)","en":"Run (Forward, Hold Forward)"}'::jsonb, 'Forward, Hold Forward', null, null, null, null, null, null, '{"ko":"Rashid''s Forward Dash can be held to initiate Run and continue running, simply hold the second Forward input after pressing Forward > Forward to dash. Run can be cancelled by holding Back or Down-Back. Rashid''s Forward Dash is 18 frames, but run doesn''t activate until frame 20.","en":"Rashid''s Forward Dash can be held to initiate Run and continue running, simply hold the second Forward input after pressing Forward > Forward to dash. Run can be cancelled by holding Back or Down-Back. Rashid''s Forward Dash is 18 frames, but run doesn''t activate until frame 20."}'::jsonb, 17),
