  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '5', '2', '7', '+4', '-1', '{"ko":"판정: 상단\nAs of March 2026 patch: can chain cancel.","en":"Hit level: High\nAs of March 2026 patch: can chain cancel."}'::jsonb, 0),
