where c.slug = 'aki' and not exists (select 1 from moves m where m.character_id = c.id);

-- ed
insert into moves (character_id, category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, patch_id, is_published, sort_order)
select c.id, v.category::move_category, v.name, v.input_classic, v.damage, v.startup, v.active, v.recovery, v.on_hit, v.on_block, v.notes,
       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '4', '3', '7', '+4', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 0),
  ('normal', '{"ko":"서서 중펀치","en":"Standing Medium Punch"}'::jsonb, '5MP', '600', '7', '3', '15', '+6', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 1),
  ('normal', '{"ko":"서서 강펀치","en":"Standing Heavy Punch"}'::jsonb, '5HP', '800', '10', '4', '18', '+5', '-2...-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 2),
