       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '5', '2', '11', '+4', '-3', '{"ko":"판정: 상단\nJune 2025 patch: active from 3 to 2 frames, on-block from -2 to -3 frames, recovery from 9 to 11 frames, total frames from 16 to 17.","en":"Hit level: High\nJune 2025 patch: active from 3 to 2 frames, on-block from -2 to -3 frames, recovery from 9 to 11 frames, total frames from 16 to 17."}'::jsonb, 0),
