  ('normal', '{"ko":"Jump Heavy Kick","en":"Jump Heavy Kick"}'::jsonb, '', '800', '10', '6', '3 Landing', '+11...', '+7...', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 21),
  ('special', '{"ko":"Kachousen (LP)","en":"Kachousen (LP)"}'::jsonb, '236LP', '500', '16', '...', '33, Flame 30', 'Normal -1..., Charged +1..., Followup +25... Flame +1..., Charged +1..., Followup +25...', 'Normal -7..., Charged -1..., Followup +21... Flame -3..., Charged -1..., Followup +21...', '{"ko":"판정: 상단\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21.","en":"Hit level: High\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21."}'::jsonb, 22),
  ('special', '{"ko":"Kachousen (MP)","en":"Kachousen (MP)"}'::jsonb, '236MP', '500', '14', '...', '35, Flame 32', 'Normal -3..., Charged +1..., Followup +25... Flame -1..., Charged +1..., Followup +25...', 'Normal -9..., Charged -1..., Followup +21... Flame -5..., Charged -1..., Followup +21...', '{"ko":"판정: 상단\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21.","en":"Hit level: High\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21."}'::jsonb, 23),
  ('special', '{"ko":"Kachousen (HP)","en":"Kachousen (HP)"}'::jsonb, '236HP', '500', '12', '...', '37, Flame 34', 'Normal -5..., Charged +1..., Followup +25... Flame -3..., Charged +1..., Followup +25...', 'Normal -11..., Charged -1..., Followup +21... Flame -7..., Charged -1..., Followup +21...', '{"ko":"판정: 상단\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21.","en":"Hit level: High\nNot technically considered a projectile, so does not collide with projectiles and can be stopped with normal attacks. Can hold the attack button to charge, and the held version is considered a projectile. Held version bounces off the opponent on hit/block for a followup hit, strength of Punch changes the bounce height. The Flame Stock version is a standard projectile with two hits. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21."}'::jsonb, 24),
  ('special', '{"ko":"Kachousen (Overdrive)","en":"Kachousen (Overdrive)"}'::jsonb, '236PP', '500', '16', '...', '31, Flame 31', 'Normal +3..., Charged +14..., Followup +25... (Knockdown +61) Flame +3..., Charged +46..., Followup +25... (Knockdown +60)', 'Normal -7..., Charged -1..., Followup +21... Flame -3..., Charged -1..., Followup +21...', '{"ko":"판정: 상단\nOverdrive version bounces off of opponents on hit/block for a followup hit without needing to be held. Overdrive version is always considered a standard projectile, but only has one hit so will lose to most other Overdrive projectiles. Can hold the attack button to charge. Held version has two hits, but does not bounce off of opponents on hit/block -- however, held version can be followed up with Forward+Punch to throw two more fans, both of which will bounce off of opponents on hit/block. Flame Stock versions still have two hits per fan. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21.","en":"Hit level: High\nOverdrive version bounces off of opponents on hit/block for a followup hit without needing to be held. Overdrive version is always considered a standard projectile, but only has one hit so will lose to most other Overdrive projectiles. Can hold the attack button to charge. Held version has two hits, but does not bounce off of opponents on hit/block -- however, held version can be followed up with Forward+Punch to throw two more fans, both of which will bounce off of opponents on hit/block. Flame Stock versions still have two hits per fan. As of March 2026 patch: on-hit / on-block of full charge bounce hit from +30 to +25 / +26 to +21."}'::jsonb, 25),
  ('special', '{"ko":"Hishou Ryuuenjin (LK)","en":"Hishou Ryuuenjin (LK)"}'::jsonb, '623LK', '400, 500 (400, 300, 300)', '5', '18', '30', 'Knockdown +29 (Knockdown +31)', '-29', '{"ko":"판정: 상단\nAnti-air invincible on frames 1-14. Flame Stock version in parenthesis.","en":"Hit level: High\nAnti-air invincible on frames 1-14. Flame Stock version in parenthesis."}'::jsonb, 26),
  ('special', '{"ko":"Hishou Ryuuenjin (MK)","en":"Hishou Ryuuenjin (MK)"}'::jsonb, '623MK', '500, 600 (500, 350, 350)', '6', '18', '29', 'Knockdown +31 (Knockdown +32)', '-28', '{"ko":"판정: 상단\nAnti-air invincible on frames 1-10. Flame Stock version in parenthesis.","en":"Hit level: High\nAnti-air invincible on frames 1-10. Flame Stock version in parenthesis."}'::jsonb, 27),
