  ('special', '{"ko":"Ryuuenbu (MP)","en":"Ryuuenbu (MP)"}'::jsonb, '214MP', '200, 800 (200, 900)', '14', '2, 7', '31', 'Knockdown +35...+41 (Limited Juggle State, Knockdown +42...)', '-6...0 (-6... 0)', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 31),
