  ('super', '{"ko":"Omega Wing Buster (Level 2, #2)","en":"Omega Wing Buster (Level 2, #2)"}'::jsonb, 'PP (during Overdrive Power Drop)', '~3000', '**', '**', '**', 'Knockdown +29', null, '{"ko":"판정: 상단\nCosts 2x super bar, only usable during Overdrive Power Drop. Scales to ~55% after Flash Chop into OD Power Drop, ~1550 in combo. Just mash PP during OD Power Drop if you have issues getting it to come out.","en":"Hit level: High\nCosts 2x super bar, only usable during Overdrive Power Drop. Scales to ~55% after Flash Chop into OD Power Drop, ~1550 in combo. Just mash PP during OD Power Drop if you have issues getting it to come out."}'::jsonb, 44),
  ('super', '{"ko":"The Final Prison (Level 3)","en":"The Final Prison (Level 3)"}'::jsonb, '236236P', '4000 (4500)', '12', '-38', '53', 'Knockdown +18 (Knockdown +25)', '**', '{"ko":"판정: 상단\nFully invincible on frames 1-11. Breaks armor. Critical Art in parenthesis.","en":"Hit level: High\nFully invincible on frames 1-11. Breaks armor. Critical Art in parenthesis."}'::jsonb, 45),
  ('throw', '{"ko":"Forward Throw","en":"Forward Throw"}'::jsonb, 'f.throw', '1200', '5', '3', '23', '+28', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 46),
  ('throw', '{"ko":"Back Throw","en":"Back Throw"}'::jsonb, 'b.throw', '1200', '5', '3', '23', '+16', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 47)
