  ('normal', '{"ko":"앉아 중펀치","en":"Crouching Medium Punch"}'::jsonb, '2MP', '600', '7', '4', '12 (15 on whiff)', '+6', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 7),
  ('normal', '{"ko":"앉아 강펀치","en":"Crouching Heavy Punch"}'::jsonb, '2HP', '800', '12', '3', '20', '+1', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 8),
  ('normal', '{"ko":"앉아 약킥","en":"Crouching Light Kick"}'::jsonb, '2LK', '200', '5', '3', '10', '+3', '-2', '{"ko":"판정: 하단","en":"Hit level: Low"}'::jsonb, 9),
  ('normal', '{"ko":"앉아 중킥","en":"Crouching Medium Kick"}'::jsonb, '2MK', '500', '8', '3', '19', '+1', '-6', '{"ko":"판정: 하단\n20% damage scaling to followup hits.","en":"Hit level: Low\n20% damage scaling to followup hits."}'::jsonb, 10),
  ('normal', '{"ko":"앉아 강킥","en":"Crouching Heavy Kick"}'::jsonb, '2HK', '900', '10', '3', '25', 'Knockdown +30', '-12', '{"ko":"판정: 하단","en":"Hit level: Low"}'::jsonb, 11),
  ('unique', '{"ko":"Forward + Medium Punch (Sun Bright)","en":"Forward + Medium Punch (Sun Bright)"}'::jsonb, 'Sun Bright', '600', '21', '4', '16', '+3', '-3', '{"ko":"판정: 중단\nCan be up to +6 on meaty.","en":"Hit level: Overhead\nCan be up to +6 on meaty."}'::jsonb, 12),
  ('unique', '{"ko":"Forward + Heavy Punch (Halo Flight)","en":"Forward + Heavy Punch (Halo Flight)"}'::jsonb, 'Halo Flight', '900', '17', '3', '21 (24 on whiff)', 'Knockdown +38', '-4', '{"ko":"판정: 상단\nCan only cancel into Air Specials, cannot Drive Rush cancel or Super Cancel.","en":"Hit level: High\nCan only cancel into Air Specials, cannot Drive Rush cancel or Super Cancel."}'::jsonb, 13),
  ('unique', '{"ko":"Back + Medium Kick","en":"Back + Medium Kick"}'::jsonb, '', '700', '9', '3', '18', '+4', '-4', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 14),
  ('unique', '{"ko":"Back + Heavy Punch","en":"Back + Heavy Punch"}'::jsonb, '', '800', '14', '5', '20', 'Limited Juggle Knockdown +45', '-8', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 15),
  ('target_combo', '{"ko":"Medium Punch, Medium Kick (Pretty Heel Kick)","en":"Medium Punch, Medium Kick (Pretty Heel Kick)"}'::jsonb, 'Pretty Heel Kick', '600, 700', '6, 12', '4, 3', '13, 23', '-3', '-11', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 16),
  ('target_combo', '{"ko":"Back + Medium Kick, Heavy Punch (Glowing Touch)","en":"Back + Medium Kick, Heavy Punch (Glowing Touch)"}'::jsonb, 'Glowing Touch', '700, 800', '9, 20', '3, 6', '18, 21', 'Knockdown +44', '-11', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 17),
  ('target_combo', '{"ko":"Back + Heavy Punch, Heavy Punch (Luminous Uppercut)","en":"Back + Heavy Punch, Heavy Punch (Luminous Uppercut)"}'::jsonb, 'Luminous Uppercut', '800, 800', '14, 23', '5, 8', '20, 16', 'Limited Juggle Knockdown +45, +43', '-8, -10', '{"ko":"판정: 상단\nOnly second hit is Special Cancellable.","en":"Hit level: High\nOnly second hit is Special Cancellable."}'::jsonb, 18),
  ('target_combo', '{"ko":"Jump Heavy Kick, Heavy Kick (Satellite Leap)","en":"Jump Heavy Kick, Heavy Kick (Satellite Leap)"}'::jsonb, 'Satellite Leap', '800, 300, 300', '12, 8', '7', '3 Landing', '**', '+6...+11', '{"ko":"판정: 중단\nTarget Combo allows air-to-air Jump Heavy Kick to followup juggle. Both the J.HK and the followup TC cause limited juggle on air hit.","en":"Hit level: Overhead\nTarget Combo allows air-to-air Jump Heavy Kick to followup juggle. Both the J.HK and the followup TC cause limited juggle on air hit."}'::jsonb, 19),
  ('normal', '{"ko":"Jump Light Punch","en":"Jump Light Punch"}'::jsonb, '', '300', '4', '10', '3 Landing', '+7...+9', '+3...+5', '{"ko":"판정: 중단","en":"Hit level: Overhead"}'::jsonb, 20),
  ('normal', '{"ko":"Jump Medium Punch","en":"Jump Medium Punch"}'::jsonb, '', '600', '8', '4', '3 Landing', '+10...+11', '+6...+7', '{"ko":"판정: 중단\nLimited Juggle State on air hit.","en":"Hit level: Overhead\nLimited Juggle State on air hit."}'::jsonb, 21),
  ('normal', '{"ko":"Jump Heavy Punch","en":"Jump Heavy Punch"}'::jsonb, '', '800', '9', '6', '3 Landing', '+9...+15', '+5...+11', '{"ko":"판정: 중단\nKnockdown on aerial counter hit.","en":"Hit level: Overhead\nKnockdown on aerial counter hit."}'::jsonb, 22),
  ('normal', '{"ko":"Jump Light Kick","en":"Jump Light Kick"}'::jsonb, '', '300', '6', '10', '3 Landing', '+5...+10', '+1...+6', '{"ko":"판정: 중단\nCrosses up.","en":"Hit level: Overhead\nCrosses up."}'::jsonb, 23),
  ('normal', '{"ko":"Jump Medium Kick","en":"Jump Medium Kick"}'::jsonb, '', '500', '8', '6', '3 Landing', '+9...+13', '+5...+9', '{"ko":"판정: 중단\nCrosses up.","en":"Hit level: Overhead\nCrosses up."}'::jsonb, 24),
  ('normal', '{"ko":"Jump Heavy Kick","en":"Jump Heavy Kick"}'::jsonb, '', '800', '12', '7', '3 Landing', '+10...+15', '+6...+11', '{"ko":"판정: 중단\nLimited Juggle State on air hit.","en":"Hit level: Overhead\nLimited Juggle State on air hit."}'::jsonb, 25),
  ('special', '{"ko":"Sun Shot (LP)","en":"Sun Shot (LP)"}'::jsonb, '236LP', '700', '17', '3', '32', '-2...+12...', '-6...+8...', '{"ko":"판정: 상단\nCreates a projectile instantly which travels forward, then delays before traveling forward again. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Light Punch causes the followup''s travel to be faster. Held Punch can be released quickly after being held, does not require waiting while the projectile delays.","en":"Hit level: High\nCreates a projectile instantly which travels forward, then delays before traveling forward again. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Light Punch causes the followup''s travel to be faster. Held Punch can be released quickly after being held, does not require waiting while the projectile delays."}'::jsonb, 26),
  ('special', '{"ko":"Sun Shot (MP)","en":"Sun Shot (MP)"}'::jsonb, '236MP', '700', '17', '3', '32', '-2...+17...', '-6...+13...', '{"ko":"판정: 상단\nCreates a projectile instantly which travels forward, then delays before traveling forward again. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Medium Punch causes the followup''s travel to be faster. Held Punch can be released quickly after being held, does not require waiting while the projectile delays.","en":"Hit level: High\nCreates a projectile instantly which travels forward, then delays before traveling forward again. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Medium Punch causes the followup''s travel to be faster. Held Punch can be released quickly after being held, does not require waiting while the projectile delays."}'::jsonb, 27),
  ('special', '{"ko":"Sun Shot (HP)","en":"Sun Shot (HP)"}'::jsonb, '236HP', '700', '15', '3', '32', '-1...+6...', '-5...+2...', '{"ko":"판정: 상단\nCreates a projectile instantly which travels up-forward, then delays before traveling down-forward. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Heavy Punch causes the followup''s travel to go forward without descending again. Held Punch can be released quickly after being held, does not require waiting while the projectile delays.","en":"Hit level: High\nCreates a projectile instantly which travels up-forward, then delays before traveling down-forward. On-hit and on-block data is only for the first travel, second travel is MUCH more advantaged as it activates entirely after she finishes recovering. Holding Heavy Punch causes the followup''s travel to go forward without descending again. Held Punch can be released quickly after being held, does not require waiting while the projectile delays."}'::jsonb, 28),
  ('special', '{"ko":"Sun Shot (Overdrive)","en":"Sun Shot (Overdrive)"}'::jsonb, '236PP', '400, 600', '17 | 17 | 15', '3', '32', 'Limited Juggle Knockdown +52... | +52... | +53...', '+1...+15... | +1...+20... | +2...+9...', '{"ko":"판정: 상단\nOD versions mimic Light, Medium, and Heavy versions but with two hits and a knockdown on hit. Data is listed as: LP+MP = Light OD | LP+HP = Medium OD | MP+HP = Heavy OD. Can hold PP to change followup''s travel behavior. Held Punch can be released quickly after being held, does not require waiting while the projectile delays.","en":"Hit level: High\nOD versions mimic Light, Medium, and Heavy versions but with two hits and a knockdown on hit. Data is listed as: LP+MP = Light OD | LP+HP = Medium OD | MP+HP = Heavy OD. Can hold PP to change followup''s travel behavior. Held Punch can be released quickly after being held, does not require waiting while the projectile delays."}'::jsonb, 29),
  ('special', '{"ko":"Sun Flare Charge (LP)","en":"Sun Flare Charge (LP)"}'::jsonb, '214LP', null, null, null, '48', null, null, '{"ko":"Charges 1x Sun Crest per use. Can hold Punch to continue charging up to 4x Sun Crests. Can be used in air on a Neutral or Forward jump. If used in air, cannot hold Punch to continue charging.","en":"Charges 1x Sun Crest per use. Can hold Punch to continue charging up to 4x Sun Crests. Can be used in air on a Neutral or Forward jump. If used in air, cannot hold Punch to continue charging."}'::jsonb, 30),
  ('special', '{"ko":"Sun Flare (Medium Punch or Heavy Punch)","en":"Sun Flare (Medium Punch or Heavy Punch)"}'::jsonb, 'Down, Down-Back, Back + Medium Punch or Heavy Punch', '900 [1x 800, 300][2x 450, 450, 450]', '21 [18] | 22 [22]', '6 [**][**]', '21 [1x 15][2x **]', 'Knockdown +47 [1x Limited Juggle Knockdown +68...][2x +76...]', '-4...-1 [1x +4...+8][+5...+9]', '{"ko":"판정: 상단\nNo difference between Medium or Heavy other than that Heavy will consume up to 2x Sun Crests, but Medium never consumes. Can be used in air on Neutral or Forward jump. 1x Crest version adds a second hit and a little extra range. 2x Crest version has three total hits and goes full screen. Data listed as: Normal [Crest] | Air [Crest]. Cannot cancel into any Super.","en":"Hit level: High\nNo difference between Medium or Heavy other than that Heavy will consume up to 2x Sun Crests, but Medium never consumes. Can be used in air on Neutral or Forward jump. 1x Crest version adds a second hit and a little extra range. 2x Crest version has three total hits and goes full screen. Data listed as: Normal [Crest] | Air [Crest]. Cannot cancel into any Super."}'::jsonb, 31),
  ('special', '{"ko":"Sun Flare (Overdrive)","en":"Sun Flare (Overdrive)"}'::jsonb, '214PP', '800, 300 [1x 450, 450, 450] [2x 450, 450, 450, 450]', '18 [18] | 22 [22]', '15 [**][**]', '21 [1x **][2x **]', '1x Limited Juggle Knockdown +68... [1x +76...][2x +87...]', '+4...+8[1x +5...+9][2x +9...+13]', '{"ko":"판정: 상단\nNon-Crest OD behaves similarly to 1x Crest Heavy. 1x Crest OD behaves similarly to 2x Creat Heavy. 2x Crest OD adds a new fourth hit and more advantage.","en":"Hit level: High\nNon-Crest OD behaves similarly to 1x Crest Heavy. 1x Crest OD behaves similarly to 2x Creat Heavy. 2x Crest OD adds a new fourth hit and more advantage."}'::jsonb, 32),
  ('special', '{"ko":"Sun Rise (LK)","en":"Sun Rise (LK)"}'::jsonb, '236LK', '1000', '8', '10', '34', 'Knockdown +36...', '-24', '{"ko":"판정: 상단\nAnti-air invincible on frames 1-14.","en":"Hit level: High\nAnti-air invincible on frames 1-14."}'::jsonb, 33),
  ('special', '{"ko":"Sun Rise (MK)","en":"Sun Rise (MK)"}'::jsonb, '236MK', '1200 (500, 700)', '13', '5, 10', '33', 'Knockdown +40...', '-23', '{"ko":"판정: 상단\nNo anti-air invincibility.","en":"Hit level: High\nNo anti-air invincibility."}'::jsonb, 34),
  ('special', '{"ko":"Sun Rise (HK)","en":"Sun Rise (HK)"}'::jsonb, '236HK', '1300 (200, 200, 500, 400)', '27', '3, 2, 4', '41', 'Knockdown +28...', '-25', '{"ko":"판정: 상단\nNo anti-air invincibility. Last hit is only a double-hit on hit, not on block or whiff.","en":"Hit level: High\nNo anti-air invincibility. Last hit is only a double-hit on hit, not on block or whiff."}'::jsonb, 35),
  ('special', '{"ko":"Sun Rise (Overdrive)","en":"Sun Rise (Overdrive)"}'::jsonb, '236KK', '1600 (200, 200, 500, 700)', '14', '5, 4, 2', '21', 'Knockdown +40...', '-3', '{"ko":"판정: 상단\nNo invincibility. Last hit is only a double-hit on hit, not on block or whiff.","en":"Hit level: High\nNo invincibility. Last hit is only a double-hit on hit, not on block or whiff."}'::jsonb, 36),
  ('special', '{"ko":"Sun Veil","en":"Sun Veil"}'::jsonb, '22K', '100, 900 (100, 1100)', '6 (1)', '15 (20)', '35', '+23 (+52)', '**', '{"ko":"판정: 상단\nNormal version absorbs projectiles and attacks on frames 6-20. OD Version absorbs projectiles, attacks, and throws on frames 1-20. Transitions into an attack when absorbing attacks and throws. OD data in parenthesis.","en":"Hit level: High\nNormal version absorbs projectiles and attacks on frames 6-20. OD Version absorbs projectiles, attacks, and throws on frames 1-20. Transitions into an attack when absorbing attacks and throws. OD data in parenthesis."}'::jsonb, 37),
  ('special', '{"ko":"Vanishing Sun","en":"Vanishing Sun"}'::jsonb, 'Back + KKK | Forward + KKK | Down + KKK', '-- | 1000 | 1100', '13 | 36 | 43', '-- | 4 | 4', '22 | 18 | 13', '** | Knockdown +44 | Limited Juggle Knockdown +48', '-- | -3 | +2', '{"ko":"판정: -- | High | Overhead\nBack version is an escape teleport with no hit. Forward version goes horizontally forward with a kick hit. Down version is an overhead jump-in kick that is plus on block and causes a juggle state on hit. Cannot cancel into any Super. Data listed as: Back | Forward | Down.","en":"Hit level: -- | High | Overhead\nBack version is an escape teleport with no hit. Forward version goes horizontally forward with a kick hit. Down version is an overhead jump-in kick that is plus on block and causes a juggle state on hit. Cannot cancel into any Super. Data listed as: Back | Forward | Down."}'::jsonb, 38),
  ('super', '{"ko":"Shining Sun (Level 1)","en":"Shining Sun (Level 1)"}'::jsonb, '236236K', '1900 | 2300 | 2700', '11', '5, 7, 3', '79', 'Knockdown +12 | +17 | +20', '-99', '{"ko":"판정: 상단\nStrike/throw invincible on frames 1-11. Breaks armor. Can hold Kick during screen freeze to consume up to 2x Crests for increased damage and knockdown advantage. Unlike Sun Flare, can choose to use 1x or 2x Crests depending on how long Kick is held during screen freeze. Data listed as: Base | 1x Crest | 2x Crest.","en":"Hit level: High\nStrike/throw invincible on frames 1-11. Breaks armor. Can hold Kick during screen freeze to consume up to 2x Crests for increased damage and knockdown advantage. Unlike Sun Flare, can choose to use 1x or 2x Crests depending on how long Kick is held during screen freeze. Data listed as: Base | 1x Crest | 2x Crest."}'::jsonb, 39),
  ('super', '{"ko":"Order of the Sun (Level 2)","en":"Order of the Sun (Level 2)"}'::jsonb, '214214P', '**', '11', '**', '**', '**', '**', '{"ko":"판정: 상단\nCauses 3x projectiles to fall from the top of the screen. Can hold Punch during screen freeze to consume up to 2x Crests to add up to 2x additional falling projectiles. Unlike Sun Flare, can choose to use 1x or 2x Crests depending on how long Punch is held during screen freeze. Tweet me with more info if you lab this weird move...","en":"Hit level: High\nCauses 3x projectiles to fall from the top of the screen. Can hold Punch during screen freeze to consume up to 2x Crests to add up to 2x additional falling projectiles. Unlike Sun Flare, can choose to use 1x or 2x Crests depending on how long Punch is held during screen freeze. Tweet me with more info if you lab this weird move..."}'::jsonb, 40),
  ('super', '{"ko":"Cosmic Ray (Level 3)","en":"Cosmic Ray (Level 3)"}'::jsonb, '236236P', '4000 (4500)', '20', '**', '**', 'Knockdown +30 (+30)', '-45', '{"ko":"판정: 상단\nHit tracks / spawns at opponent, goes full screen. Critical Art in parenthesis.","en":"Hit level: High\nHit tracks / spawns at opponent, goes full screen. Critical Art in parenthesis."}'::jsonb, 41),
  ('throw', '{"ko":"Forward Throw","en":"Forward Throw"}'::jsonb, 'f.throw', '1200', '5', '3', '23', '+21', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 42),
  ('throw', '{"ko":"Back Throw","en":"Back Throw"}'::jsonb, 'b.throw', '1200', '5', '3', '23', '+20', null, '{"ko":"판정: 잡기","en":"Hit level: Throw"}'::jsonb, 43)
) as v(category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, ord)
where c.slug = 'ingrid' and not exists (select 1 from moves m where m.character_id = c.id);

-- yasmine
insert into moves (character_id, category, name, input_classic, damage, startup, active, recovery, on_hit, on_block, notes, patch_id, is_published, sort_order)
select c.id, v.category::move_category, v.name, v.input_classic, v.damage, v.startup, v.active, v.recovery, v.on_hit, v.on_block, v.notes,
       (select id from patches order by released_on desc limit 1), false, v.ord
from characters c, (values
  ('normal', '{"ko":"서서 약펀치","en":"Standing Light Punch"}'::jsonb, '5LP', '300', '5', '3', '7', '+4', '-1', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 0),
