  ('normal', '{"ko":"서서 약킥","en":"Standing Light Kick"}'::jsonb, '5LK', '300', '5', '2', '12', '+2', '-4', '{"ko":"판정: 상단","en":"Hit level: High"}'::jsonb, 3),
